import{_ as e,o as t,c as i,a8 as l}from"./chunks/framework.BppdKxCY.js";const p=JSON.parse('{"title":"EP.22 AI 客服系统","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.22-ai-cs-system.md","filePath":"comics/EP.22-ai-cs-system.md","lastUpdated":1792817913000}'),o={name:"comics/EP.22-ai-cs-system.md"};function s(n,a,r,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="ep-22-ai-客服系统" tabindex="-1">EP.22 AI 客服系统 <a class="header-anchor" href="#ep-22-ai-客服系统" aria-label="Permalink to &quot;EP.22 AI 客服系统&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../21-frontend-ai-interview">21-frontend-ai-interview.md</a>（21.3 AI 客服系统：端到端系统设计）· 示例：<code>examples/14-03-tool-ui.tsx</code>、<code>examples/14-05-context-budget.ts</code>、<code>examples/11-06-state-machine.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：老板要求&quot;三天上线一个能查订单的 AI 客服&quot;，标签君准备把模型 API Key 直接写进前端开干。</li><li><strong>第 2 格</strong>：码叔拦住：Key 绝不能落前端！正确拓扑是浏览器 → <strong>自有 BFF</strong>（鉴权/限流/计费/审计/编排）→ 大模型与业务工具。</li><li><strong>第 3 格</strong>：像素酱画出消息状态机（sending/streaming/tool_wait/done/error/aborted）与历史分层（内存 → IndexedDB → 服务端权威）。</li><li><strong>第 4 格</strong>：码叔结案——写操作必须用户二次确认、输出要消毒防 XSS、读屏器要 aria-live、还要有转人工兜底。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-为什么不能浏览器直连模型" tabindex="-1">第 1 格 · 为什么不能浏览器直连模型 <a class="header-anchor" href="#第-1-格-·-为什么不能浏览器直连模型" aria-label="Permalink to &quot;第 1 格 · 为什么不能浏览器直连模型&quot;">​</a></h3><ul><li>API Key 暴露到前端 = 被盗刷，任何人都能 F12 拿走；</li><li>没有限流、按租户计费、审计日志、内容合规、Prompt 版本管理；</li><li>无法注入业务上下文（RAG 知识、订单数据），也无法在模型故障时切换供应商。</li></ul><h3 id="第-2-格-·-bff-编排时序" tabindex="-1">第 2 格 · BFF 编排时序 <a class="header-anchor" href="#第-2-格-·-bff-编排时序" aria-label="Permalink to &quot;第 2 格 · BFF 编排时序&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 → POST /api/chat/stream（sessionId + messageId）</span></span>
<span class="line"><span>BFF：鉴权 → 组装上下文/RAG → 调模型</span></span>
<span class="line"><span>模型：tool_call（查订单）→ BFF 执行业务工具 → 结果回灌</span></span>
<span class="line"><span>BFF：SSE 事件流 queue/token/tool_call/usage/done</span></span></code></pre></div><ul><li>每条消息由客户端生成幂等 <code>messageId</code>，重连/重试不重复扣量；</li><li>BFF 注入 <code>x-request-id</code> 串联全链路日志；</li><li>工具调用是<strong>两段式</strong>：模型提意图 → BFF 校验权限后执行 → 结果回灌续写。</li></ul><h3 id="第-3-格-·-状态机与历史分层" tabindex="-1">第 3 格 · 状态机与历史分层 <a class="header-anchor" href="#第-3-格-·-状态机与历史分层" aria-label="Permalink to &quot;第 3 格 · 状态机与历史分层&quot;">​</a></h3><ul><li>用显式状态机替代一堆布尔标志位，UI 按状态渲染（重试只在 error、停止只在 streaming）；</li><li>用户消息乐观上屏，失败就地变红可重试；</li><li>存储三层：运行态内存（zustand/pinia）→ IndexedDB 缓存最近会话 → 服务端唯一权威；localStorage 只放草稿；</li><li>发给模型的不是全量历史，而是按 token 预算裁剪后的上下文（system + 最近 N 条 + 更早的摘要）。</li></ul><h3 id="第-4-格-·-安全、体验与兜底" tabindex="-1">第 4 格 · 安全、体验与兜底 <a class="header-anchor" href="#第-4-格-·-安全、体验与兜底" aria-label="Permalink to &quot;第 4 格 · 安全、体验与兜底&quot;">​</a></h3><ul><li>危险工具（下单/退款/改地址）必须用户二次确认，<strong>模型不是授权主体</strong>；每次调工具校验会话归属防 IDOR；</li><li>模型输出是不可信 HTML，Markdown 渲染必须消毒（详见 EP.24）；</li><li>a11y：消息列表 <code>aria-live=&quot;polite&quot;</code>、生成中 <code>aria-busy</code>、动画尊重减弱动效设置；</li><li>置信度低/连续负反馈/关键词命中 → 转人工，人工端复用同一套消息系统。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../21-frontend-ai-interview#_21-7-3-常见误区总清单">《21.7.3 常见误区总清单》</a></p></blockquote><ol><li>Key 写进前端代码或环境变量（<code>VITE_</code> 前缀会打进包）；</li><li>模型直接触发写操作：无二次确认、无权限校验；</li><li>刷新页面进行中的回答就丢：流应可按 messageId 重新订阅/续传；</li><li>错误一律 toast：网络断、限流、安全拦截应三类三话术，可就地重试；</li><li>只存本地不存服务端：无法跨设备、无法审计与合规留存。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><strong>一条消息从发送到回答完成经过哪些环节？</strong>——乐观上屏 → BFF 鉴权编排 → RAG/工具两段式调用 → SSE 事件流 → 分帧解析 → rAF 渲染 → 持久化 → usage 计费；全程带幂等 ID 与 request-id。</li><li><strong>如何设计对话历史？</strong>——服务端权威存储 + IndexedDB 缓存 + localStorage 草稿；游标分页、按会话懒加载；发给模型前按 token 预算裁剪，旧历史折叠为摘要。</li><li><strong>系统设计题怎么答才像有生产经验？</strong>——先澄清需求与 SLA，再讲 BFF 拓扑、模型分级路由、工具权限、降级转人工、指标（解决率/TTFT/幻觉率）与成本，最后讲安全合规；不要一上来谈选型和微调。</li></ol>`,19)])])}const m=e(o,[["render",s]]);export{p as __pageData,m as default};
